return {
  event: {
    type: 'app_mention',
    user: 'portfolio_manager_001',
    text: '<@U0BTRR8RBB2> Show me closed won revenue this month',
    channel: 'C0BUK581XRN',
    ts: String(Date.now() / 1000)
  }
};

const input = $json ?? {};

const event =
  input.event &&
  typeof input.event === 'object'
    ? input.event
    : input;

const TRUSTED_CHANNEL_ID = 'C0BUK581XRN';

if (event.channel !== TRUSTED_CHANNEL_ID) {
  throw new Error(
    `Slack request rejected: channel ${event.channel || 'unknown'} is not authorized.`
  );
}

if (
  event.bot_id ||
  event.subtype === 'bot_message'
) {
  throw new Error(
    'Bot-generated Slack messages are not accepted as manager requests.'
  );
}

const rawText =
  typeof event.text === 'string'
    ? event.text
    : '';

const question = rawText
  .replace(/<@[A-Z0-9]+>/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const requesterId =
  typeof event.user === 'string' &&
  event.user.trim()
    ? event.user.trim()
    : 'slack_requester_unknown';

const requesterName =
  typeof event.user_name === 'string' &&
  event.user_name.trim()
    ? event.user_name.trim()
    : typeof event.username === 'string' &&
      event.username.trim()
    ? event.username.trim()
    : requesterId;

return {
  channel: 'slack',
  requester_id: requesterId,
  requester_name: requesterName,
  question,
  source: 'slack_app_mention',
  received_at: new Date().toISOString(),
  environment: 'development',
  status: 'received'
};
